var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`LEEJISOO_SIX_SUMMER_NULL`,text:{KOREA:`그 모든 징조들이... 오늘을 가리키고 있었군. 그래. 장래에 기다리는 고난들을 당신이 어떻게 헤쳐 나가나 지켜봐 주겠어. 기대를 저버리진 마.`,JPN:`そうか、今までの兆候は……今日を指し示していたんだな。ならば、この先に待つ困難をお前がどう乗り越えていくのか見守っていよう。期待を裏切るな。`,ENG:`All the omens... have been pointing towards today. Okay. I'll keep an eye on you to see how you overcome the tribulations awaiting you. Don't let me down.`,TWN:`所有的徵兆……指的原來就是今天啊。好，你會怎麼克服在未來等著你的苦難，我會好好看著的。不要辜負我的期待啊。`},stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`LEEJISOO_SIX_SUMMER_NULL`,face:`UNIT_LAUGH`,hologram:!1},R:null}}}];export{e as default};